export const RON=.047,LOAD=100;
export function voltages(board,{power,drive,fault,time=5}){if(!power)return Object.fromEntries(board.nets.map(n=>[n.name,0]));if(board.educational){const vin=drive==='high'?5:0;let out=0;if(board.kind==='divider')out=fault==='rOpen'?0:fault==='r2Open'?vin:vin/2;if(board.kind==='rc')out=fault==='capShort'||fault==='rOpen'?0:vin*(1-Math.exp(-Math.max(0,time)));if(board.kind==='led')out=fault==='ledOpen'?vin:fault==='ledShort'||fault==='rOpen'?0:Math.min(vin,2);return {VIN:vin,OUT:out,GND:0};}if(board.id==='mosfet'){let on=drive==='high'||fault==='qShort';return {GND:0,VCC:5,CONTROL:drive==='high'?5:0,'HIGH-CURRENT':on?(fault==='qShort'?0:5*RON/(LOAD+RON)):5};}let v={GND:0,LV:3.3,HV:5};for(let i=1;i<=4;i++){v['LV'+i]=i===1&&drive==='low'?0:3.3;v['HV'+i]=i===1&&drive==='low'?0:5;}return v;}
export function resistance(board,na,nb,fault='none'){if(na===nb)return 0;let edges=[];for(const el of board.elements){if(!el.name.startsWith('R')||fault==='rOpen'&&el.name==='R1'||fault==='r2Open'&&el.name==='R2')continue;let p=el.pads.map(id=>board.pads.find(p=>p.id===id));if(p.length===2)edges.push([p[0].net,p[1].net,el.ohms||10000]);}if(board.educational&&['capShort','ledShort'].includes(fault))edges.push(['OUT','GND',.001]);if(fault==='qShort'&&board.id==='mosfet')edges.push(['HIGH-CURRENT','GND',.001]);let dist={[na]:0},visited=new Set();for(;;){let node=Object.keys(dist).filter(n=>!visited.has(n)).sort((a,b)=>dist[a]-dist[b])[0];if(!node)return Infinity;if(node===nb)return dist[node];visited.add(node);for(const [a,b,r]of edges){let next=a===node?b:b===node?a:null;if(next&&(!Object.hasOwn(dist,next)||dist[next]>dist[node]+r))dist[next]=dist[node]+r;}}}
export function measure(board,state){const a=board.pads.find(p=>p.id===state.red),b=board.pads.find(p=>p.id===state.black);if(!a||!b)return {display:'— —',unit:state.mode==='voltage'?'V':'Ω',status:'COLOCA LAS DOS PUNTAS',hint:'Selecciona una punta y toca un pad dorado.',value:null};if(state.mode!=='voltage'&&state.power)return {display:'STOP',unit:'',status:'DESCONECTA LA ALIMENTACIÓN',hint:'No se mide continuidad ni resistencia con tensión.',value:null};if(board.exploreOnly){const same=a.net===b.net;return {display:state.mode==='continuity'?(same?'0.00':'—'):'—',unit:state.mode==='continuity'?'Ω':'',status:board.representative?'RED DIDÁCTICA · SIN SIMULACIÓN':'CONECTIVIDAD CAD · SIN SIMULACIÓN',hint:state.mode==='continuity'?(same?'Misma red del diseño. Continuidad ideal del cobre.':'Redes distintas: no implica circuito abierto; pueden unirse por componentes.'):'Esta placa permite seguir redes y bloques; no calcula tensiones ni resistencias.',value:state.mode==='continuity'&&same?0:null};}if(state.mode==='voltage'){let v=voltages(board,state);let val=v[a.net]-v[b.net];return {display:(Math.abs(val)<.0005?0:val).toFixed(3),unit:'V',status:state.power?'TENSIÓN CONTINUA · MODELO DC':'FUENTE DESCONECTADA · SIN CARGA',hint:`${a.id} (${a.net}) − ${b.id} (${b.net})`,value:val};}let r=resistance(board,a.net,b.net,state.fault);return {display:Number.isFinite(r)?(r>=1000?(r/1000).toFixed(2):r.toFixed(2)):'OL',unit:r>=1000&&Number.isFinite(r)?'kΩ':'Ω',status:state.mode==='continuity'?(r<30?'● CONTINUIDAD EN EL MODELO':'SIN CONTINUIDAD DIRECTA'):'RED RESISTIVA IDEAL',hint:board.educational?'Modelo resistivo: fuente retirada; condensador abierto y diodo no modelado.':'Fuente y carga externas retiradas. No incluye uniones de MOSFET.',value:r};}
